## 复杂度分析

- 时间复杂度：对于每组测试数据，计算行和列和需要 $O(r \times c)$，枚举行和列的组合需要 $O(r \times c)$。所有测试用例的总元素个数不超过 $5\times 10^5$，因此总时间复杂度为 $O(总元素数)$，可以在时限内完成。
- 空间复杂度：需要存储矩阵以及行和、列和，空间复杂度为 $O(r \times c)$。

## 代码实现

### Python

```python
import sys

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    q = int(next(it))
    out_lines = []
    for _ in range(q):
        r = int(next(it))
        c = int(next(it))
        matrix = []
        row_sum = [0] * r
        col_sum = [0] * c
        for i in range(r):
            row = []
            for j in range(c):
                val = int(next(it))
                row.append(val)
                row_sum[i] += val
                col_sum[j] += val
            matrix.append(row)
        # 两次选择同一行或同一列的情况：等效于只取一次
        ans = max(row_sum + col_sum)
        # 两次选择两个不同的行
        if r >= 2:
            a = b = -10**18
            for v in row_sum:
                if v >= a:
                    b = a
                    a = v
                elif v > b:
                    b = v
            ans = max(ans, a + b)
        # 两次选择两个不同的列
        if c >= 2:
            a = b = -10**18
            for v in col_sum:
                if v >= a:
                    b = a
                    a = v
                elif v > b:
                    b = v
            ans = max(ans, a + b)
        # 一次行一次列
        for i in range(r):
            for j in range(c):
                ans = max(ans, row_sum[i] + col_sum[j] - matrix[i][j])
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (q-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int r = Integer.parseInt(st.nextToken());
            int c = Integer.parseInt(st.nextToken());
            long[][] mat = new long[r][c];
            long[] rowSum = new long[r];
            long[] colSum = new long[c];
            for (int i = 0; i < r; i++) {
                st = new StringTokenizer(br.readLine());
                for (int j = 0; j < c; j++) {
                    mat[i][j] = Long.parseLong(st.nextToken());
                    rowSum[i] += mat[i][j];
                    colSum[j] += mat[i][j];
                }
            }
            long ans = Long.MIN_VALUE;
            // 同一行/列两次
            for (long v : rowSum) ans = Math.max(ans, v);
            for (long v : colSum) ans = Math.max(ans, v);
            // 两个不同的行
            if (r >= 2) {
                long a = Long.MIN_VALUE, b = Long.MIN_VALUE;
                for (long v : rowSum) {
                    if (v >= a) {
                        b = a;
                        a = v;
                    } else if (v > b) {
                        b = v;
                    }
                }
                ans = Math.max(ans, a + b);
            }
            // 两个不同的列
            if (c >= 2) {
                long a = Long.MIN_VALUE, b = Long.MIN_VALUE;
                for (long v : colSum) {
                    if (v >= a) {
                        b = a;
                        a = v;
                    } else if (v > b) {
                        b = v;
                    }
                }
                ans = Math.max(ans, a + b);
            }
            // 一行一列
            for (int i = 0; i < r; i++) {
                for (int j = 0; j < c; j++) {
                    ans = Math.max(ans, rowSum[i] + colSum[j] - mat[i][j]);
                }
            }
            sb.append(ans).append('\n');
        }
        System.out.print(sb);
    }
}
```

